/* Decode a Shift_JIS byte pair to a glyph pointer, or nullptr if the
   pair is outside JIS X 0208 rows 1..JIS208_ROW_END or otherwise invalid. */
static inline const uint8_t* sjis_glyph(uint8_t lead, uint8_t trail) {
  /* Lead-byte sanity. SJIS leads: 0x81..0x9F and 0xE0..0xFC. */
  if (lead < 0x81) return nullptr;
  if (lead > 0x9F && lead < 0xE0) return nullptr;
  if (lead > 0xFC) return nullptr;
  /* Trail-byte sanity: 0x40..0x7E or 0x80..0xFC. */
  if (trail < 0x40 || trail == 0x7F || trail > 0xFC) return nullptr;

  uint8_t row;
  if (lead < 0xE0) {
    row = ((lead - 0x81) << 1) + 1;  /* odd row of the lead pair */
  } else {
    row = ((lead - 0xC1) << 1) + 1;
  }
  uint8_t cell;
  if (trail < 0x9F) {
    cell = trail - ((trail >= 0x80) ? 0x40 : 0x3F);
  } else {
    cell = trail - 0x9E;
    row += 1;  /* even row */
  }
  if (row < JIS208_ROW_START || row > JIS208_ROW_END) return nullptr;
  if (cell < 1 || cell > 94) return nullptr;

  uint32_t idx = (uint32_t)(row - JIS208_ROW_START) * 94 + (cell - 1);
  return JIS208 + idx * JIS208_BYTES_PER_GLYPH;
}
